async function main() {
  const ids = Object.keys(stories);
  console.log(`Uploading stories for ${ids.length} places...`);

  let ok = 0;
  let fail = 0;
  for (const id of ids) {
    try {
      await db.collection('places').doc(id).update({ story: stories[id] });
      console.log(`  ✓ ${id}`);
      ok++;
    } catch (err) {
      console.error(`  ✗ ${id}: ${err.message}`);
      fail++;
    }
  }
  console.log(`\nDone: ${ok} updated, ${fail} failed.`);
}

main();
